  path: string,
  schema: z.ZodType<T>,
  init: RequestInit
): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${getMobileEnv().EXPO_PUBLIC_API_URL}${path}`, init);
  } catch {
    throw new ApiClientError(
      "无法连接服务器，请检查网络和 API 地址",
      "NETWORK_ERROR"
    );
  }
  return parseResponse(response, schema);
}

