import {
  expirySegmentBounds,
  foodSchema,
  type Food,
  type FoodCounts,
  type FoodCreate,
  type FoodListQuery,
  type FoodProcess,
  type FoodUpdate
} from "@freshtrack/contracts";
import {
  Prisma,
  type Food as PrismaFood,
  type PrismaClient
} from "@prisma/client";

import { AppError } from "./errors.js";

export interface FoodService {
  create(userId: string, input: FoodCreate): Promise<Food>;
  get(userId: string, foodId: string): Promise<Food>;
  update(userId: string, foodId: string, input: FoodUpdate): Promise<Food>;
  delete(userId: string, foodId: string): Promise<void>;
  list(userId: string, query: FoodListQuery): Promise<Food[]>;
  counts(userId: string, today: string): Promise<FoodCounts>;
  process(userId: string, foodId: string, input: FoodProcess): Promise<Food>;
  restore(userId: string, foodId: string): Promise<Food>;
}

function dateFromCalendar(value: string): Date {
  return new Date(`${value}T00:00:00.000Z`);
}

function calendarFromDate(value: Date): string {
  return value.toISOString().slice(0, 10);
}

function toFood(food: PrismaFood): Food {
  return foodSchema.parse({
    id: food.id,
    name: food.name,
    category: food.category,
    quantity: food.quantity.toFixed(3),
    unit: food.unit,
    expiryDate: calendarFromDate(food.expiryDate),
    reminderEnabled: food.reminderEnabled,
    notes: food.notes,
    status: food.status,
    processedAt: food.processedAt?.toISOString() ?? null,
    createdAt: food.createdAt.toISOString(),
    updatedAt: food.updatedAt.toISOString()
  });
}

function inputData(input: FoodCreate) {
  return {
    name: input.name,
    category: input.category,
    quantity: new Prisma.Decimal(input.quantity),
    unit: input.unit,
    expiryDate: dateFromCalendar(input.expiryDate),
    reminderEnabled: input.reminderEnabled,
    notes: input.notes
  };
}

function inaccessibleFood(): AppError {
  return new AppError("NOT_FOUND", "食品不存在或不可操作", 404);
}

function segmentWhere(
  segment: FoodListQuery["segment"],
  today: string | undefined
): Prisma.DateTimeFilter | undefined {
  if (segment === "all" || today === undefined) {
    return undefined;
  }
  const bounds = expirySegmentBounds(segment, today);
  if ("before" in bounds) {
    return { lt: dateFromCalendar(bounds.before) };
  }
  if ("exact" in bounds) {
    return { equals: dateFromCalendar(bounds.exact) };
  }
  return {
    gte: dateFromCalendar(bounds.after),
    lte: dateFromCalendar(bounds.through)
  };
}

export function createFoodService(prisma: PrismaClient): FoodService {
  async function findOwned(userId: string, foodId: string): Promise<PrismaFood> {
    const food = await prisma.food.findFirst({
      where: { id: foodId, userId }
    });
    if (!food) {
      throw inaccessibleFood();
    }
    return food;
  }

  return {
    async create(userId, input) {
      return toFood(
        await prisma.food.create({
          data: { userId, ...inputData(input) }
        })
      );
    },

    async get(userId, foodId) {
      return toFood(await findOwned(userId, foodId));
    },

    async update(userId, foodId, input) {
      const result = await prisma.food.updateMany({
        where: { id: foodId, userId, status: "ACTIVE" },
        data: inputData(input)
      });
      if (result.count !== 1) {
        throw inaccessibleFood();
      }
      return toFood(await findOwned(userId, foodId));
    },

    async delete(userId, foodId) {
      const result = await prisma.food.deleteMany({
        where: { id: foodId, userId }
      });
      if (result.count !== 1) {
        throw inaccessibleFood();
      }
    },

    async list(userId, query) {
      const isActive = query.view === "active";
      const expiryDate = isActive
        ? segmentWhere(query.segment, query.today)
        : undefined;
      const where: Prisma.FoodWhereInput = {
        userId,
        status: isActive
          ? "ACTIVE"
          : query.status === "all"
            ? { in: ["EATEN", "DISCARDED"] }
            : query.status,
        ...(query.search
          ? { name: { contains: query.search, mode: "insensitive" } }
          : {}),
        ...(query.category ? { category: query.category } : {}),
        ...(expiryDate ? { expiryDate } : {})
      };
      const orderBy: Prisma.FoodOrderByWithRelationInput[] = isActive
        ? query.sort === "expiry"
          ? [{ expiryDate: "asc" }, { createdAt: "desc" }, { id: "asc" }]
          : [{ createdAt: "desc" }, { id: "asc" }]
        : [{ processedAt: "desc" }, { id: "asc" }];
      const foods = await prisma.food.findMany({
        where,
        orderBy,
        take: query.limit
      });
      return foods.map(toFood);
    },

    async counts(userId, today) {
      const todayDate = dateFromCalendar(today);
      const next3Bounds = expirySegmentBounds("next3", today);
      if (!("after" in next3Bounds)) {
        throw new Error("Unexpected next-three-days bounds");
      }
      const tomorrow = dateFromCalendar(next3Bounds.after);
      const through = dateFromCalendar(next3Bounds.through);
      const [all, expired, dueToday, next3] = await prisma.$transaction([
        prisma.food.count({ where: { userId, status: "ACTIVE" } }),
        prisma.food.count({
          where: { userId, status: "ACTIVE", expiryDate: { lt: todayDate } }
        }),
        prisma.food.count({
          where: { userId, status: "ACTIVE", expiryDate: todayDate }
        }),
        prisma.food.count({
          where: {
            userId,
            status: "ACTIVE",
            expiryDate: { gte: tomorrow, lte: through }
          }
        })
      ]);
      return { all, expired, today: dueToday, next3 };
    },

    async process(userId, foodId, input) {
      const result = await prisma.food.updateMany({
        where: { id: foodId, userId, status: "ACTIVE" },
        data: { status: input.status, processedAt: new Date() }
      });
      if (result.count !== 1) {
        throw inaccessibleFood();
      }
      return toFood(await findOwned(userId, foodId));
    },

    async restore(userId, foodId) {
      const result = await prisma.food.updateMany({
        where: {
          id: foodId,
          userId,
          status: { in: ["EATEN", "DISCARDED"] }
        },
        data: { status: "ACTIVE", processedAt: null }
      });
      if (result.count !== 1) {
        throw inaccessibleFood();
      }
      return toFood(await findOwned(userId, foodId));
    }
  };
}
# Picker

`Picker` 是底部弹出的滚轮选择器，负责普通单列选择和树形级联选择。它的核心语义是：

- `value/defaultValue/onChange` 表示“已确认值”，只在点击确认后提交。
- 打开弹层后使用内部 draft，滚轮滚动不会污染外部表单值。
- 需要实时联动时监听 `onDraftChange`。
- 默认数据结构是 `{ value, label, children, disabled }`，其它数据结构用 accessor 适配。

## 基础用法

```tsx
import * as React from 'react';
import { Text } from 'zkit-ui/text';
import { Picker } from 'zkit-ui/picker';

const options = [
  { value: 'design', label: 'Design' },
  { value: 'motion', label: 'Motion' },
  { value: 'release', label: 'Release' },
];

export function Demo() {
  const [value, setValue] = React.useState<string | number>();

  return (
    <Picker
      options={options}
      value={value}
      valueMode="single"
      onChange={(next) => setValue(Array.isArray(next) ? next[0] : next)}
      placeholder="请选择"
    >
      {({ label, placeholder }) => <Text>{label || placeholder}</Text>}
    </Picker>
  );
}
```

## 级联选择

```tsx
const options = [
  {
    value: 'zj',
    label: '浙江省',
    children: [
      { value: 'hz', label: '杭州市' },
      { value: 'nb', label: '宁波市' },
    ],
  },
  {
    value: 'js',
    label: '江苏省',
    children: [
      { value: 'nj', label: '南京市' },
      { value: 'sz', label: '苏州市' },
    ],
  },
];

export function Demo() {
  const [value, setValue] = React.useState<string[]>();

  return (
    <Picker
      options={options}
      value={value}
      valueMode="path"
      separator=" / "
      onChange={(next) => setValue(Array.isArray(next) ? next.map(String) : [String(next)])}
    >
      {({ label }) => <Text>{label || '选择地区'}</Text>}
    </Picker>
  );
}
```

## 适配外部数据

主 API 不再暴露 `valueKey/labelKey` 这类字符串配置。外部数据字段不一致时，用 accessor 明确适配：

```tsx
const rawOptions = [
  { id: 1, title: '选项一' },
  { id: 2, title: '选项二', children: [{ id: 21, title: '子项' }] },
];

<Picker
  options={rawOptions}
  getOptionValue={(item) => item.id}
  getOptionLabel={(item) => item.title}
  getOptionChildren={(item) => item.children}
/>;
```

## 自定义列标题

```tsx
<Picker
  options={options}
  renderColumnHeader={({ columnIndex }) => (
    <Text>{['省份', '城市', '区县'][columnIndex]}</Text>
  )}
/>;
```

## 命令式打开

```tsx
const ref = React.useRef<PickerHandle>(null);

<Picker ref={ref} options={options} />;

ref.current?.open();
ref.current?.close();
```

## Types

```ts
type PickerPrimitiveValue = string | number;
type PickerValue = PickerPrimitiveValue | PickerPrimitiveValue[];
type PickerValueMode = 'auto' | 'single' | 'path';

type PickerOption = {
  value: PickerPrimitiveValue;
  label: string;
  disabled?: boolean;
  children?: PickerOption[];
  key?: React.Key;
  testID?: string;
  accessibilityLabel?: string;
};

type PickerSelection<TOption = PickerOption> = {
  value: PickerValue;
  values: PickerPrimitiveValue[];
  label: string;
  labels: string[];
  items: TOption[];
  columns: TOption[][];
  indices: number[];
  isComplete: boolean;
};
```

## Props

| Prop | Type | Default | Description |
| --- | --- | --- | --- |
| `options` | `readonly TOption[]` | required | 数据源，默认读取 `value/label/children/disabled` |
| `value` | `PickerValue` | - | 受控的已确认值 |
| `defaultValue` | `PickerValue` | - | 非受控初始值 |
| `onChange` | `(value, selection) => void` | - | 点击确认后提交已确认值 |
| `valueMode` | `'auto' \| 'single' \| 'path'` | `'auto'` | 输出单值还是路径数组；级联建议显式用 `path` |
| `open` | `boolean` | - | 受控打开状态 |
| `defaultOpen` | `boolean` | `false` | 非受控初始打开状态 |
| `onOpenChange` | `(open: boolean) => void` | - | 打开状态变化 |
| `onDismissComplete` | `() => void` | - | Sheet 完全关闭后触发 |
| `title` | `string` | i18n `picker.title` | 弹层标题 |
| `placeholder` | `string` | `''` | 无已确认值时给 trigger 使用 |
| `cancelText` | `string` | i18n `picker.cancel` | 取消按钮文案 |
| `confirmText` | `string` | i18n `picker.confirm` | 确认按钮文案 |
| `emptyText` | `string` | i18n `picker.empty` | 空数据文案 |
| `separator` | `string` | `'-'` | 多列 label 拼接分隔符 |
| `formatLabel` | `(selection) => string` | - | 自定义最终 label |
| `renderColumnHeader` | `(context) => ReactNode` | - | 自定义列标题 |
| `maxColumns` | `number` | `5` | 最多渲染列数，内部限制 1-8 |
| `lazyContent` | `boolean` | `true` | 打开时再挂载滚轮内容，关闭后卸载 |
| `sheetHeight` | `number \| 'auto'` | `'auto'` | 底部弹层高度；数字按 RN dp 解释 |
| `disabled` | `boolean` | `false` | 禁用打开、滚动和按钮 |
| `onCancel` | `() => void` | - | 取消或点背景关闭时触发 |
| `onConfirm` | `(selection) => void` | - | 点击确认后触发，晚于 `onChange` |
| `onDraftChange` | `(selection) => void` | - | 滚轮草稿变化时触发，不提交外部值 |
| `children` | `ReactNode \| (context) => ReactNode` | - | 触发器内容 |

Accessor props:

| Prop | Type |
| --- | --- |
| `getOptionValue` | `(option, index, path) => PickerPrimitiveValue \| undefined` |
| `getOptionLabel` | `(option, index, path) => string \| number \| undefined` |
| `getOptionChildren` | `(option, index, path) => readonly TOption[] \| undefined` |
| `isOptionDisabled` | `(option, index, path) => boolean` |

## 设计取舍

- `label/defaultLabel/onLabelChange` 不再作为 Picker 状态。label 是由已确认 `value + options` 推导出的展示结果，业务需要自定义显示时使用 `formatLabel` 或 trigger render context。
- `onChange` 表示最终表单值变化，和 TextInput、Radio、CheckboxGroup 的状态事件保持一致。
- iOS 保留原生 `UIPickerView`，Android/Web 继续走自绘 wheel。Picker 层只处理级联状态和弹层生命周期，不把额外 JS 工作塞进滚轮关键帧。
