+        body: `${input.foodName} 的到期日是 ${input.expiryDate}`,
+        data: {
+          source: "freshtrack",
+          userId: input.userId,
+          foodId: input.foodId
+        }
+      },
+      trigger: {
+        type: Notifications.SchedulableTriggerInputTypes.DATE,
+        date: input.trigger,
+        channelId: REMINDER_CHANNEL_ID
+      }
+    });
+  },
+
+  cancel(identifier) {
+    return Notifications.cancelScheduledNotificationAsync(identifier);
+  },
